const SectionDivider = () => (
  <div className="flex items-center gap-3 my-16 md:my-20">
    <div className="flex-1 h-px bg-border" />
    <Star size={8} className="text-muted-foreground/30 fill-muted-foreground/30" />
    <Star size={12} className="text-muted-foreground/30 fill-muted-foreground/30" />
    <Star size={8} className="text-muted-foreground/30 fill-muted-foreground/30" />
    <div className="flex-1 h-px bg-border" />
  </div>
);

const ItemGrid = ({ items, onItemClick }: { items: { name: string; year: string; image: string | null; description?: string; objectPosition?: string }[]; onItemClick?: (item: any) => void }) => (
  <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
    {items.map((item) => (
      <div
        key={item.name}
        className={`group ${item.description ? 'cursor-pointer' : ''}`}
        onClick={() => item.description && onItemClick?.(item)}
      >
        <div className="aspect-video overflow-hidden bg-muted/30 border border-border mb-2 flex items-center justify-center">
          {item.image ? (
            <img
              src={item.image}
              alt={item.name}
              loading="lazy"
              className="w-full h-full object-cover photo-grayscale"
              style={item.objectPosition ? { objectPosition: item.objectPosition } : undefined}
            />
          ) : (
            <span className="text-[10px] text-muted-foreground/50 text-center px-1 font-mono">{item.name}</span>
          )}
        </div>
        <p className="text-[10px] text-muted-foreground leading-tight">{item.name}</p>
        <p className="text-[9px] text-muted-foreground/50 font-mono">{item.year}</p>
      </div>
    ))}
  </div>
);

